// BarFrame draws one line of content inside the rectangle that closes the
// viewport, and the rectangle's bottom edge under it.
//
// The viewport's own bottom border serves as the top of the rectangle, so the
// two lines here are the sides and the floor. The router turns that border's
// └ ┘ into ├ ┤ when a BarFrame opens the footer (OpensWithBarFrame):
//
//	├────────────────────────────────────┤

//	│  / cursor...                    Aa │
//	└────────────────────────────────────┘
//
// It is shared rather than copied because two things now occupy that one slot —
// the filter bar and the viewer's go-to-line prompt — and a second
// implementation of the frame would be free to disagree with the first about
// where the corners are. `inner` is already styled; it is padded to the width
// between the sides, so a caller measures nothing.
func BarFrame(width int, inner string) string {
	if width == 0 {
		width = 80
	}

	borderStyle := lipgloss.NewStyle().Foreground(theme.ColorViewportBorder).Background(theme.ColorBackground)

	// width-2 to leave room for │ on each side.
	padded := theme.PadWithBg(inner, width-2)
	content := borderStyle.Render("│") + padded + borderStyle.Render("│")
	bottom := borderStyle.Render("└" + strings.Repeat("─", width-2) + "┘")
	return content + "\n" + bottom
}

// OpensWithBarFrame reports whether a rendered footer starts with a BarFrame:
// a first line framed by │ on both sides and a second line closed by └…┘. The
// router reads it to turn the viewport's bottom corners into ├ ┤, so the join
// follows what the footer really draws rather than what a view claims.
func OpensWithBarFrame(footer string) bool {
	lines := strings.SplitN(ansi.Strip(footer), "\n", 3)
	if len(lines) < 2 {
		return false
	}
	return strings.HasPrefix(lines[0], "│") && strings.HasSuffix(lines[0], "│") &&
		strings.HasPrefix(lines[1], "└") && strings.HasSuffix(lines[1], "┘")
}
}

// fitHeight stacks header, body and footer in at most height lines.
// lipgloss.Place pads a short block but never crops a tall one, so on a very
// small terminal (header 8 + title 1 + the viewport's minimum + footer) the
// frame would be taller than the screen. The surplus is taken from the body
// first: the footer carries the messages, so it outranks viewport rows. The
// lines taken sit just above the body's last line, so the viewport's bottom
// border (or the junction a bar attaches to) survives the cut; a body cut
// entirely is simply gone. If header and footer alone are taller than the terminal, the
// stack is cut to its first height lines, the simplest floor. At normal
// heights nothing is cut.
func fitHeight(header, body, footer string, height int) string {
	parts := []string{header}
	if body != "" {
		parts = append(parts, body)
	}
	if footer != "" {
		parts = append(parts, footer)
	}
	lines := strings.Split(strings.Join(parts, "\n"), "\n")
	excess := len(lines) - height
	if height <= 0 || excess <= 0 {
		return strings.Join(lines, "\n")
	}

	headerLen := strings.Count(header, "\n") + 1
	bodyLen := 0
	if body != "" {
		bodyLen = strings.Count(body, "\n") + 1
	}
	cut := min(excess, bodyLen)
	if cut > 0 {
		end := headerLen + bodyLen
		if cut < bodyLen {
			end-- // keep the body's last line
		}
		lines = append(lines[:end-cut], lines[end:]...)
	}
	if len(lines) > height {
		lines = lines[:height]
	}
	return strings.Join(lines, "\n")
}

// activeOverlay returns the overlay to draw instead of the view, or "" when
// there is none. The order matches the one handleKeyMsg dispatches in, so the
// overlay holding the keyboard is the one on screen.
func (a *App) activeOverlay() string {
	switch {
	case a.switchingTo != "":
		return a.renderContextSwitchingOverlay()
	case a.showHelp:
		return a.renderHelpOverlay()
	case a.showContextList:
		return a.renderContextListOverlay()
	}
	return ""
}

// renderBody fills the viewport with the active view's content, padded to the
// full inner width so no line shows the terminal's own background (Rule 115).
// barBelow is true when the footer opens with a components.BarFrame: the
// viewport's bottom corners then become T-junctions (Rule 136).
func (a *App) renderBody(barBelow bool) string {
	content := "View not found: " + string(a.currentView)
	if view, ok := a.views[a.currentView]; ok {
